"use client"

import { useState, useEffect } from "react"
import { Star, ThumbsUp, Loader2, PenLine } from "lucide-react"
import { Progress } from "@/components/ui/progress"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Label } from "@/components/ui/label"
import { supabase } from "@/lib/supabase"
import { useToast } from "@/hooks/use-toast"

import { useAuth } from "@/components/auth/auth-provider"

interface Review {
    id: number
    author: string
    date: string
    rating: number
    text: string
    helpful: number
}

interface ProductReviewsProps {
    productId: string
    reviews: Review[]
    rating: number
    totalReviews: number
}

export default function ProductReviews({ productId, reviews, rating, totalReviews }: ProductReviewsProps) {
    const { user } = useAuth()
    const [canReview, setCanReview] = useState(false)
    const [showForm, setShowForm] = useState(false)
    const [loading, setLoading] = useState(false)
    const { toast } = useToast()

    // Check Purchase History
    useEffect(() => {
        async function checkPurchase() {
            if (!user) {
                setCanReview(false)
                return
            }

            const { data } = await supabase
                .from('order_items')
                .select('id, order:orders!inner(user_id)')
                .eq('product_id', productId)
                .eq('order.user_id', user.id)
                .limit(1)

            if (data && data.length > 0) {
                setCanReview(true)
            }
        }
        checkPurchase()
    }, [user, productId])

    // Form State
    const [newReview, setNewReview] = useState({
        name: "",
        rating: 5,
        comment: ""
    })

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault()
        setLoading(true)

        try {
            const { error } = await supabase.from('reviews').insert({
                product_id: productId,
                user_name: newReview.name,
                rating: newReview.rating,
                comment: newReview.comment,
                status: 'Pending' // Requires admin approval
            })

            if (error) throw error

            toast({
                title: "Review Submitted!",
                description: "Your review is pending approval."
            })
            setShowForm(false)
            setNewReview({ name: "", rating: 5, comment: "" })
        } catch (error: any) {
            console.error(error)
            toast({
                title: "Submission Failed",
                description: "Could not submit review.",
                variant: "destructive"
            })
        } finally {
            setLoading(false)
        }
    }

    return (
        <section id="reviews" className="space-y-8">
            <div className="flex items-center justify-between">
                <h2 className="text-2xl font-bold">Customer Reviews</h2>
                {canReview ? (
                    <Button onClick={() => setShowForm(!showForm)} variant="outline" className="gap-2">
                        <PenLine className="w-4 h-4" />
                        Write a Review
                    </Button>
                ) : (
                    user ? (
                        <p className="text-sm text-muted-foreground italic bg-secondary/30 px-3 py-1.5 rounded-md">
                            Verified purchasers only
                        </p>
                    ) : (
                        <p className="text-sm text-muted-foreground italic">
                            Log in to review
                        </p>
                    )
                )}
            </div>

            {/* Write Review Form */}
            {showForm && (
                <div className="bg-card border border-border rounded-xl p-6 animate-in slide-in-from-top-4">
                    <h3 className="font-bold mb-4">Write your review</h3>
                    <form onSubmit={handleSubmit} className="space-y-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <Label>Your Name</Label>
                                <Input
                                    required
                                    value={newReview.name}
                                    onChange={e => setNewReview({ ...newReview, name: e.target.value })}
                                    placeholder="John Doe"
                                />
                            </div>
                            <div className="space-y-2">
                                <Label>Rating</Label>
                                <div className="flex gap-1 py-2">
                                    {[1, 2, 3, 4, 5].map((star) => (
                                        <button
                                            key={star}
                                            type="button"
                                            onClick={() => setNewReview({ ...newReview, rating: star })}
                                            className="focus:outline-none"
                                        >
                                            <Star
                                                className={`w-6 h-6 ${star <= newReview.rating ? "fill-yellow-400 text-yellow-400" : "text-input"}`}
                                            />
                                        </button>
                                    ))}
                                </div>
                            </div>
                        </div>
                        <div className="space-y-2">
                            <Label>Review</Label>
                            <Textarea
                                required
                                value={newReview.comment}
                                onChange={e => setNewReview({ ...newReview, comment: e.target.value })}
                                placeholder="Tell us what you liked or didn't like containing..."
                            />
                        </div>
                        <div className="flex justify-end gap-2">
                            <Button type="button" variant="ghost" onClick={() => setShowForm(false)}>Cancel</Button>
                            <Button type="submit" disabled={loading}>
                                {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                                Submit Review
                            </Button>
                        </div>
                    </form>
                </div>
            )}

            <div className="grid md:grid-cols-3 gap-8">
                {/* Summary */}
                <div className="md:col-span-1 space-y-6">
                    <div className="text-center md:text-left">
                        <div className="text-5xl font-bold text-foreground mb-2">{rating || 0}</div>
                        <div className="flex justify-center md:justify-start gap-1 mb-2">
                            {[...Array(5)].map((_, i) => (
                                <Star
                                    key={i}
                                    className={`w-5 h-5 ${i < Math.floor(rating || 0) ? "fill-accent text-accent" : "text-border"
                                        }`}
                                />
                            ))}
                        </div>
                        <p className="text-muted-foreground">{totalReviews} verified reviews</p>
                    </div>

                    <div className="space-y-2">
                        {[5, 4, 3, 2, 1].map((star) => (
                            <div key={star} className="flex items-center gap-3 text-sm">
                                <span className="w-3 font-medium">{star}</span>
                                <Star className="w-4 h-4 text-muted-foreground" />
                                <Progress value={0} className="h-2" /> {/* Placeholder distribution */}
                                <span className="w-8 text-right text-muted-foreground">0%</span>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Reviews List */}
                <div className="md:col-span-2 space-y-6">
                    {reviews.length === 0 ? (
                        <div className="text-center py-12 text-muted-foreground">
                            No reviews yet. Be the first to write one!
                        </div>
                    ) : reviews.map((review) => (
                        <div key={review.id} className="border-b border-border pb-6 last:border-0">
                            <div className="flex items-center justify-between mb-2">
                                <div className="flex items-center gap-2">
                                    <div className="font-semibold">{review.author}</div>
                                    <span className="text-xs text-muted-foreground">• {review.date}</span>
                                </div>
                                <div className="flex gap-0.5">
                                    {[...Array(5)].map((_, i) => (
                                        <Star
                                            key={i}
                                            className={`w-3.5 h-3.5 ${i < review.rating ? "fill-accent text-accent" : "text-border"
                                                }`}
                                        />
                                    ))}
                                </div>
                            </div>
                            <p className="text-muted-foreground text-sm mb-4">{review.text}</p>
                            <button className="flex items-center gap-2 text-xs text-muted-foreground hover:text-foreground transition">
                                <ThumbsUp className="w-3.5 h-3.5" />
                                Helpful ({review.helpful})
                            </button>
                        </div>
                    ))}
                </div>
            </div>
        </section>
    )
}
